#!/usr/bin/env python3
"""Builds the Utilities and energy saving training deck. Run: python3 tools/decks/utilities-energy-saving.py"""
import sys, os
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from deck_lib import *

S = []
S.append(cover('cover', 'Plant utilities training', 'Utilities:<br>where the<br>money leaks', 'Steam, water, chillers and compressed air in a batch plant, and how to save energy without hurting the process',
 "Welcome. Utilities are the quiet cost behind every batch: steam, cooling water, chilled water, compressed air, nitrogen, power and vacuum. Nobody sees them on a batch record, yet they show up in our monthly bill. Today we look at where utility energy is wasted in a plant like ours, how to size the loss with simple arithmetic, and which fixes pay back fastest. Keep it practical. I will ask you questions throughout, and at the end you will test your own numbers on live calculators. First question: which utility do you think costs us the most per month? Keep your answer, we will come back to it."))

S.append(stats('hook', 'Small holes, large bills', [('7', 'utilities run behind every batch'), ('~20', 'kg/h of steam lost through one 3 mm hole at 8 barg'), ('~2.6 kW', 'power wasted by one 3 mm air leak at 7 barg')],
 'You can hear a leak. You cannot see the bill.',
 "These numbers are calculated, not measured, and you will redo them yourself on the live page. Seven utilities sit behind every batch. A trap passing steam through a hole the size of a pencil lead loses about twenty kilograms of steam every hour. (Click.) A single compressed air leak of the same size keeps a compressor motor working about two and a half kilowatts harder, all day and all night. (Click.) Ask the room: how many leaks do you think we have on the floor right now? Most people guess too low. The point of today is to turn noise into rupees.", theme='light'))

S.append(table('map', 'The utility map of a batch plant', ['Utility', 'Made from', 'Used for', 'Common waste'],
 [['Steam', 'Fuel in a boiler', 'Heating, distillation, drying', 'Leaks, bare pipes, lost condensate'],
  ['Cooling water', 'Cooling tower', 'Condensers, jackets', 'Low cycles, over-circulation'],
  ['Chilled water, brine', 'Chiller or VAM', 'Low-temperature condensing', 'Cold losses, wrong set point'],
  ['Compressed air', 'Air compressor', 'Valves, instruments, tools', 'Leaks, high pressure'],
  ['Nitrogen', 'PSA plant or cylinders', 'Inerting, blanketing', 'Over-purging'],
  ['Power', 'Grid and DG set', 'Motors, lighting', 'Idle running, oversized motors'],
  ['Vacuum', 'Pumps and ejectors', 'Distillation, drying', 'Air ingress, wrong pump']],
 "Here is the whole map on one slide. Read across each row: what makes the utility, what we use it for, and where it usually goes to waste. (Click for each row.) Notice that almost every utility is made by burning fuel or using electricity, so a saving anywhere is a saving in the boiler house or at the transformer. Ask the room to add a row we missed. Someone usually says hot oil or hot water. Write it on the board. Today we focus on steam, cooling water, chilled water and compressed air, because that is where simple fixes pay back quickly.", theme='dark'))

S.append(bullets('steam', 'Steam carries heat as latent heat', ['Boiling water into steam absorbs a large amount of heat', 'That heat comes back out when steam condenses on a jacket or coil', 'Condensate leaves still hot, with a good share of the energy', 'So every kilogram of steam we waste is fuel we paid for'],
 "Start with the physics in plain words. To turn a kilogram of water into steam at the same temperature takes about two thousand kilojoules. That is roughly five hundred times what it takes to warm the same water by one degree. (Click.) When steam condenses on our reactor jacket it gives that heat back. (Click.) The condensate is hot water, still carrying heat. (Click.) So steam is a heat delivery system. Ask the room: when steam escapes from a leaking flange, what are we throwing away? Fuel, treated water and chemicals together. Keep that triple loss in mind.", theme='light', callout=('~2050 kJ/kg', 'Latent heat of steam at about 8 barg. Hot water gives only 4.2 kJ/kg for each degree.')))

S.append(guess('quarter', 'Guess: how much heat is left in the condensate?', 'Steam gives up its latent heat at 8 barg. What share of the steam\'s total heat is still in the hot condensate leaving the heater?',
 'about a quarter', 'Roughly 740 kJ out of about 2770 kJ per kg. This is why condensate return pays, and why flash steam from it is worth capturing.',
 "Let the room guess before the click. Most say close to zero, because the condensate looks like water. Collect three or four numbers on the board. (Click.) The answer is about a quarter. At eight bar gauge, a kilogram of steam carries about 2770 kilojoules, and the saturated condensate still holds roughly 740 of them. If that condensate goes to drain, we throw away the heat, the treated water and the chemicals in it. Ask: where does our condensate go today, back to the boiler or to the drain? That one answer tells us a lot about the plant.", theme='dark'))

S.append(table('traps', 'Steam traps: four types, one job', ['Type', 'How it works', 'Good for', 'Watch for'],
 [['Thermodynamic', 'Flash steam presses a disc shut', 'Mains, tracing, small sizes', 'Cycles fast and wears when dirty'],
  ['Float and thermostatic', 'Float opens on condensate', 'Heat exchangers, jackets', 'Float punctures, air vents stick'],
  ['Inverted bucket', 'Steam lifts a bucket to close', 'General process use', 'Loses its water seal and blows'],
  ['Thermostatic', 'Element senses temperature', 'Tracing, air venting', 'Slow response to load changes']],
 "A steam trap has one job: let condensate and air out and keep steam in. There are four common types. Read the table with me. (Click per row.) Each has a different way of sensing condensate, so each fails in a different way. A float trap fails when the float gets punctured. An inverted bucket fails when it loses its water seal after a pressure drop. Ask the room: which type do we mostly have, and does anyone know how many traps we have in total? If nobody knows, that is finding number one. You cannot manage what you have not counted.", theme='light'))

S.append(compare('trapfail', 'Two ways a trap fails', ('Blowing open', ['Live steam goes straight to the condensate line', 'Visible as a steam plume at the vent or a hot return line', 'Costs fuel every hour it runs', 'Often found, rarely repaired quickly']), ('Stuck closed', ['Condensate cannot leave the heater', 'Slow heat-up, water hammer, cold spots', 'Shows up as longer batch times', 'Costs production, not just steam']),
 "Traps fail in two directions. On the left, blowing open. This is the leak you can lose a lot of money on, because steam passes straight through to the return line. (Click.) On the right, stuck closed. The heater fills with condensate, heat-up gets slow, and you may get water hammer. (Click.) The first wastes fuel. The second wastes batch time, which can cost more. Ask: which of these would an operator notice first? Usually the second, because the batch runs late. That is why blowing traps live for years. A routine trap survey with an ultrasonic or temperature tester catches both.", theme='dark'))

S.append(bullets('flash', 'Condensate and flash steam are worth keeping', ['Return condensate to the boiler feed tank', 'Treated, hot water: saves fuel, water and chemicals', 'Condensate at high pressure makes flash steam when pressure drops', 'Use flash steam for low-pressure heating instead of venting it'],
 "Four short points. Return condensate to the feed tank. (Click.) It is already treated and already hot, so we save fuel, water and chemicals together. (Click.) Condensate from a high-pressure heater flashes into steam when the pressure drops. (Click.) That white cloud from a vent pipe is flash steam, and it is fuel we paid for. We can use it in a low-pressure heater or a deaerator. Ask: have you seen a plume at a drain or vent on the roof? That is a project waiting to happen. Quality matters too. Contaminated condensate must be tested before it goes back to the boiler.", theme='light', callout=('Return it', 'Hot condensate also raises feedwater temperature, which cuts the fuel the boiler needs.')))

S.append(bullets('boiler', 'The boiler house: four simple checks', ['Stack temperature: hot flue gas is heat going up the chimney', 'Excess air: too much air carries heat out, too little makes soot', 'Blowdown: controlling dissolved solids without dumping hot water', 'Insulation: bare valves, flanges and tanks lose heat all day'],
 "Four checks, all cheap. First, stack temperature. If the flue gas is much hotter than it needs to be, we are heating the sky. (Click.) Second, excess air. A burner running with too much air sends heat out of the stack. Too little air gives smoke and lost fuel. An oxygen analyser tells you. (Click.) Third, blowdown. We must remove dissolved solids, but an uncontrolled continuous blowdown dumps hot treated water. Heat recovery from blowdown helps. (Click.) Fourth, insulation. A bare flange loses far more heat than people expect. Ask: who has touched a pipe that was too hot to hold, and why was it uninsulated?", theme='dark'))

S.append(table('tower', 'Cooling tower words you must know', ['Term', 'Meaning', 'Why it matters'],
 [['Range', 'Hot water in minus cold water out', 'Sets how much heat is removed'],
  ['Approach', 'Cold water minus wet-bulb temperature', 'Shows how well the tower performs'],
  ['Evaporation', 'Water that leaves as vapour', 'The real cooling, and the main loss'],
  ['Cycles of concentration', 'Dissolved solids in the loop versus make-up', 'Sets blowdown and water cost']],
 "Four words that every plant engineer should own. Range is the temperature drop across the tower. (Click.) Approach is how close the cold water gets to the wet-bulb temperature of the air. A small approach means a well-working tower. (Click.) Evaporation is the real cooling, about one percent of the circulation for each six degrees of range. (Click.) Cycles of concentration tell us how many times the dissolved salts are concentrated compared with make-up water. Ask the room: do we know the cycles at our tower? If we do not measure conductivity, we do not know. The next slides show why it matters.", theme='light'))

S.append(guess('evap', 'Guess: how much water does a tower evaporate?', 'A tower circulates 500 m3/h with a 6 C range. How much water leaves as vapour every hour?',
 '~4.6 m3/h', 'About 1 percent of the circulation. It is roughly 0.00153 times the range in degrees C times the circulation. Blowdown and make-up come on top of this.',
 "Let the room guess first. Most people say a tiny amount, or half the flow. Write the numbers on the board. (Click.) The answer is about 4.6 cubic metres an hour, a bit under one percent of the circulation. The rule of thumb is evaporation equals 0.00153 times the range in degrees Celsius times the circulation rate. Over a year of 8000 hours that is thirty-six thousand cubic metres, before we count any blowdown. Ask: where does the rest of the make-up water go? To blowdown, to drift and to leaks. Next slide, blowdown depends on cycles.", theme='dark'))

S.append(table('cycles', 'More cycles, less water', ['Cycles', 'Blowdown, m3/h', 'Make-up, m3/h'],
 [['2', '4.6', '9.2'], ['3', '2.3', '6.9'], ['4', '1.5', '6.1'], ['5', '1.1', '5.7'], ['6', '0.9', '5.5']],
 "Same tower, evaporation fixed at 4.6 cubic metres an hour. Blowdown equals evaporation divided by cycles minus one. At two cycles we blow down as much as we evaporate. (Click through the rows.) Going from two to five cycles cuts make-up from 9.2 to 5.7, about a third. After five or six the gains flatten, and the water chemistry risk of scale and corrosion grows. So the target is a sensible number set with the water treatment supplier, not the highest number. Ask: what limits cycles at our tower, hardness, silica or chlorides? Your water analysis answers that. All values are illustrative for the example tower.", theme='light', note='Illustrative: 500 m3/h, 6 C range, evaporation 4.6 m3/h, drift ignored.'))

S.append(compare('chvam', 'Chiller or VAM?', ('Electric chiller', ['Runs on electricity', 'COP often around 4 to 6 (illustrative)', 'Cost follows the power tariff', 'Efficient at part load with the right controls']), ('Vapour absorption (VAM)', ['Runs on steam, hot water or hot gas', 'Thermal COP around 0.7 for single effect (illustrative)', 'Cost follows the heat price', 'Attractive with waste heat']),
 "Two ways to make chilled water. The electric chiller uses a compressor, so its running cost follows the power tariff. Its coefficient of performance, the cooling you get per unit of electricity, is often four to six. (Click.) The vapour absorption machine uses heat instead. Its thermal COP is lower, around 0.7 for a single effect, but heat can be cheap if we have spare steam or waste heat. COP numbers here are illustrative. Ask the room: which of our chillers runs on steam, and what does that steam really cost us? The honest answer needs both prices, which we will test live in a moment.", theme='dark'))

S.append(bullets('chwin', 'When does each machine win?', ['Cheap or waste heat available: the VAM can win', 'Heat made by burning fuel for the purpose: compare carefully', 'Electricity cheap or heat expensive: the chiller usually wins', 'Compare on the price of the energy you really save'],
 "No machine always wins. If we have spare low-pressure steam or waste heat, VAM turns a cost into cooling. (Click.) If steam is made in a boiler just for the chiller, calculate. (Click.) If electricity is cheap or steam is dear, the electric machine is likely cheaper. (Click.) The last line is the key. Use the cost of the marginal energy, not an average blended rate. Ask: what happens to our steam when the plant load drops? If the boiler turns down, steam saved is fuel saved. If steam would be vented anyway, it is free. The calculator lets you find the break-even steam price for your own numbers.", theme='light', callout=('1 TR = 3.517 kW', 'Cooling duty of one tonne of refrigeration. Use it to compare both machines on the same load.')))

S.append(bullets('air', 'Compressed air is the costliest utility per unit of work', ['Making air takes a lot of electricity for a small amount of useful energy', 'Typical compressors need about 6 to 7 kW for each m3/min (illustrative)', 'Higher pressure costs more power and increases every leak', 'Lower the set point to what the plant really needs'],
 "Compressed air feels free because the hose never runs out. It is not free. Most of the electricity is turned into heat in the compressor. (Click.) As a round figure, six to seven kilowatts for each cubic metre per minute of free air, though your compressor datasheet is the real number. (Click.) Higher pressure costs more power. A common rule is a few percent for every bar. And a higher pressure pushes more air through every leak. (Click.) So find the highest pressure that any user really needs, and set the compressor there. Ask: who set our pressure, and when did anyone last check it? Often nobody.", theme='dark', callout=('Pressure is a choice', 'Every extra bar costs power and widens every leak.')))

S.append(table('leaks', 'What a leak costs a year', ['Hole size', 'Air lost, m3/min', 'Power, kW', 'Rs per year'],
 [['1 mm', '0.04', '0.3', '~18,000'], ['3 mm', '0.40', '2.6', '~165,000'], ['5 mm', '1.10', '7.2', '~460,000']],
 "These are calculated for seven bar gauge, 6.5 kilowatts per cubic metre per minute, power at eight rupees a unit and 8000 hours a year. Change any of them and the answers change, so use your own tariff. (Click for each row.) The size matters twice: doubling the hole diameter quadruples the flow. (Click.) A five millimetre leak, which you can easily hear, is about forty thousand rupees every month at these assumptions. Ask: if we find twenty leaks of mixed size, what could the total be? Use the live page to test it. Then ask who owns the leak repair tag system on the floor.", theme='light', note='Illustrative: 7 barg, 6.5 kW per m3/min, Rs 8 per kWh, 8000 h. Enter your own on the live page.'))

S.append(mythfact('myths', 'Myth or fact?', [('A bigger trap is a safer trap.', 'Myth', 'An oversized trap can cycle badly and wear faster. Size it for the load.'), ('Raising cooling tower cycles saves water.', 'Fact', 'Less blowdown, less make-up. Within what the water treatment allows.'), ('A small air leak is not worth fixing.', 'Myth', 'Small leaks run all day and add up across a plant.')],
 "Three claims. (Click.) A bigger trap is safer. Myth. An oversized trap can cycle badly and wears out faster. We size traps for the actual load and pressure. Ask a supervisor if they have ever swapped in a bigger trap to stop water hammer. (Click.) Raising cycles saves water. Fact, as long as the chemistry allows it. Ask the water treatment lead what limit applies at our tower. (Click.) A small air leak is not worth fixing. Myth. Small leaks run all day, and a plant has many. A whole plant of small leaks can waste a compressor's worth of power. End by asking which myth you believed before today.", theme='dark'))

S.append(bullets('measure', 'Measure first: specific energy per kilogram', ['Track each utility per kg of product, not just in total', 'Steam per kg, power per kg and water per kg tell you when something drifts', 'Use meters, a sheet and a monthly review', 'A utility with no meter has no owner'],
 "If we only look at the monthly bill, we cannot tell a saving from a quiet month. Compare utility per kilogram of product instead. (Click.) Steam per kilogram, kilowatt-hours per kilogram, water per kilogram. When the number drifts up, something changed. (Click.) We do not need a fancy system. A meter, a spreadsheet and a short monthly review are enough to start. (Click.) And the last point is a management rule: a utility with no meter has no owner, and what has no owner leaks. Ask: which utility at our plant has no meter? That meter is probably your best first investment.", theme='light', callout=('kWh per kg', 'Specific energy removes the effect of production volume.')))

S.append(compare('wins', 'Quick wins and capital projects', ('Quick wins', ['Repair traps and air leaks', 'Insulate bare valves and flanges', 'Lower the compressor set pressure', 'Raise cooling tower cycles within limits']), ('Capital projects', ['Condensate recovery system', 'Economiser on the boiler', 'Variable speed drives on fans and pumps', 'VAM using waste heat']),
 "Sort the ideas into two lists. Quick wins on the left cost little and often pay back in months. They need attention, not budget. (Click.) Capital projects on the right need design, a quote and approval, and pay back over one to three years. Do the quick wins first. They build credibility and sometimes fund the larger ones. Ask the room to shout one item for each list from our own plant and write them down. Then ask who will own each action and by what date. A list without owners and dates is just a wish.", theme='dark'))

S.append(table('payback', 'Worked example: a ranked savings list', ['Measure', 'Saving, lakh/yr', 'Cost, lakh', 'Payback'],
 [['Raise tower cycles', '2.5', '0.5', '2.4 months'], ['Fix air leaks', '3.5', '0.8', '2.7 months'], ['Repair steam traps', '6.0', '1.5', '3 months'], ['Insulate valves and flanges', '4.0', '2.0', '6 months'], ['Condensate return', '9.0', '12.0', '16 months']],
 "All numbers here are illustrative, to show the method. Simple payback is cost divided by annual saving. Rank by payback. (Click through.) The first four measures pay back within half a year and total about sixteen lakh rupees of saving for a spend of under five lakh. (Click.) Condensate return costs more and takes sixteen months, but saves a lot every year after. Simple payback ignores interest and the life of the measure, so it is a screening tool, not a final decision. Ask: if you could only fund one measure this quarter, which would you pick and why? Then try your own on the planner.", theme='light', note='Illustrative values. Replace them with your own audit data and quotes.'))

S.append(live('tryit', 'Now you call it: five live checks', [('Steam trap leak:', 'what does a blowing trap cost?'), ('Cooling tower:', 'evaporation, blowdown and make-up'), ('Chiller or VAM:', 'which is cheaper on your prices?'), ('Compressed air leak:', 'what one hole costs a year'), ('Condensate return:', 'fuel and water saved')],
 "Open the live page now: pharmacheme.in/training/modules/utilities-energy-saving/live/ (the button on the module page opens it in a new tab). It has the five stations in this order, plus a savings planner. Tick show answers immediately if you want to skip the reveal. Each station is illustrative: enter our own tariffs and numbers, set the conditions, ask the room to estimate, then reveal. Pick people from different roles: ask a supervisor about the trap, an engineer about the cooling tower, the plant head about the chiller or VAM choice. About twenty minutes for all five, then ten for the planner."))

S.append(rules('rules', 'Five rules to take back to the plant', ['Count and survey your traps every year.', 'Return the condensate, use the flash steam.', 'Know your tower cycles and set them with your water supplier.', 'Fix the air leaks, then lower the set pressure.', 'Meter every utility and track energy per kg.'],
 "Read the five rules aloud and ask the room to repeat the first one. Then take questions. If time allows, ask each table to pick one rule and name the first action, owner and date for it. The best result from today is a short list on the board with names beside it. Remind everyone that all the numbers we used were illustrative. The calculators are on the live page, free to use, so each person can try their own pressure, tariff and hole size. Thank the room, and ask who will volunteer to lead the first trap survey."))

n = build('utilities-energy-saving', 'Utilities and energy saving', S)
print(n, 'slides')
